\begin{aligned}
\operatorname{LineOK}_{510}(\Gamma,\pi,i)
\Longleftrightarrow{}&
(A_i\in\Gamma\land\Delta_i=\{A_i\})\\
&\lor(A_i\in\mathsf{Ax}_{510}\land\Delta_i=\varnothing)\\
&\lor\bigl(\exists j,k<i\;
(((A_j,A_k),A_i)\in\mathsf{Rule}_{MP}^{510}
\land\Delta_i=\Delta_j\cup\Delta_k)\bigr)\\
&\lor\bigl(\exists j<i\;\exists x\in\mathsf{Var}_{510}\;
(A_i=\forall x\,A_j
\land ((A_j),A_i)\in\mathsf{Rule}_{Gen}^{510}\\
&\hspace{36mm}\land x\notin\bigcup_{G\in\Gamma}\operatorname{FV}_{510}(G)
\land\Delta_i=\Delta_j)\bigr)\\
&\lor\bigl(\exists j,k<i\;
(((A_j,A_k),A_i)\in\mathsf{Rule}_{Cov}^{510}
\land\Delta_i=\Delta_j\cup\Delta_k)\bigr)\\
&\lor\bigl(\exists j<i\;
(A_j\equiv_{\alpha,510}A_i\land\Delta_i=\Delta_j)\bigr).
\end{aligned}
